/* 학습 해설
 * KMSAN report의 세 조기 반환과 억제 depth
 * 미초기화·해제 후 사용·외부 정보 유출 보고를 읽고 현재 사용과 과거 생성·저장 원인을 실제 Linux 코드로 추적합니다.
 * 보고는 검사 비활성, current depth 비영, origin0을 차례로 제외합니다. 정상 보고에 들어갈 때 disable_current로 depth를 증가시켜 재귀 보고를 억제합니다. runtime guard와 보고 억제 depth가 별개라는 앞 hook 수업을 실제 출력 조건에 연결합니다.
 * 세 조기 반환에서는 lock·uaccess 저장·로그가 없는지 확인하세요. 정상 보고 종료 뒤 depth0로 복구하는 균형을 적고 nested 보고를 억제하는 이유를 공유 buffer·console 재진입과 연결합니다.
 */
void kmsan_report(depot_stack_handle_t origin, void *address, int size,
		  int off_first, int off_last, const void __user *user_addr,
		  enum kmsan_bug_reason reason)
{
	unsigned long stack_entries[KMSAN_STACK_DEPTH];
	int num_stack_entries, skipnr;
	char *bug_type = NULL;
	unsigned long ua_flags;
	bool is_uaf;

	if (!kmsan_enabled)
		return;
	if (current->kmsan_ctx.depth)
		return;
	if (!origin)
		return;

	kmsan_disable_current();
	ua_flags = user_access_save();
	raw_spin_lock(&kmsan_report_lock);
	pr_err("=====================================================\n");
	is_uaf = kmsan_uaf_from_eb(stack_depot_get_extra_bits(origin));
	switch (reason) {
	case REASON_ANY:
		bug_type = is_uaf ? "use-after-free" : "uninit-value";
		break;

