/* 학습 해설
 * KMSAN 미래 구간 목록과 작은 데이터의 선형 탐색
 * 부팅 초기의 주소 구간·고정 배열·LIFO stack·page block 분할과 metadata 자원 준비를 실제 Linux 코드로 이해합니다.
 * 부팅 때 아직 page allocator가 준비되지 않은 구간을 start/end 배열에 기록합니다. 용량은128이고 주석의 실제 예상 구간 수는20미만이라 복잡한 tree 대신 선형 탐색을 선택합니다. 자료구조의 선택은 최대 상수뿐 아니라 실제 데이터 수·초기화 제약·구현 비용과 연결됩니다.
 * 작은 예약 구간 몇 개를 배열에 적고 각 추가의 비교 횟수를 세어 보세요. 이 기록은 metadata 즉시 할당이 아니라 나중 초기화를 위한 목록이며 실제 page 확보와 분리합니다.
 */
static void __init kmsan_record_future_shadow_range(void *start, void *end)
{
	u64 nstart = (u64)start, nend = (u64)end, cstart, cend;
	bool merged = false;

	KMSAN_WARN_ON(future_index == NUM_FUTURE_RANGES);
	KMSAN_WARN_ON((nstart >= nend) ||
		      /* Virtual address 0 is valid on s390. */
		      (!IS_ENABLED(CONFIG_S390) && !nstart) ||
		      !nend);
	nstart = ALIGN_DOWN(nstart, PAGE_SIZE);
	nend = ALIGN(nend, PAGE_SIZE);

	/*
	 * Scan the existing ranges to see if any of them overlaps with
	 * [start, end). In that case, merge the two ranges instead of
	 * creating a new one.
	 * The number of ranges is less than 20, so there is no need to organize
	 * them into a more intelligent data structure.
	 */
	for (int i = 0; i < future_index; i++) {
		cstart = start_end_pairs[i].start;
		cend = start_end_pairs[i].end;
		if ((cstart < nstart && cend < nstart) ||
		    (cstart > nend && cend > nend))
			/* ranges are disjoint - do not merge */

