/* 학습 해설
 * KMSAN init_shadow 입력·reserved·data·NUMA node
 * 부팅 초기의 주소 구간·고정 배열·LIFO stack·page block 분할과 metadata 자원 준비를 실제 Linux 코드로 이해합니다.
 * shadow 초기화는 reserved physical 구간을 phys_to_virt로 옮겨 기록하고 .data 구간과 online node의 NODE_DATA 구조체 구간도 기록합니다. 각 source 범위를 page 단위로 합친 뒤 metadata를 준비합니다. 함수 앞 주석의 넓은 개요와 실제 본문의 등록 호출을 구별합니다.
 * 모델 reserved2구간·data·node2개가 인접 병합으로3개 최종 구간이 되는지 확인하세요. NUMA node 구조체96byte는 모델 타입이며 실제 kernel pg_data_t layout과 물리 변환을 실행하지 않습니다.
 */
void __init kmsan_init_shadow(void)
{
	const size_t nd_size = sizeof(pg_data_t);
	phys_addr_t p_start, p_end;
	u64 loop;
	int nid;

	for_each_reserved_mem_range(loop, &p_start, &p_end)
		kmsan_record_future_shadow_range(phys_to_virt(p_start),
						 phys_to_virt(p_end));
	/* Allocate shadow for .data */
	kmsan_record_future_shadow_range(_sdata, _edata);

	for_each_online_node(nid)
		kmsan_record_future_shadow_range(
			NODE_DATA(nid), (char *)NODE_DATA(nid) + nd_size);

	for (int i = 0; i < future_index; i++)
		kmsan_init_alloc_meta_for_range(
			(void *)start_end_pairs[i].start,
			(void *)start_end_pairs[i].end);
}

