/* 학습 해설
 * KMSAN order별 held_back와 두 metadata block
 * 부팅 초기의 주소 구간·고정 배열·LIFO stack·page block 분할과 metadata 자원 준비를 실제 Linux 코드로 이해합니다.
 * held_back는 order마다 shadow·origin 두 포인터를 보관합니다. 같은 order 첫 block은 shadow, 둘째는 origin으로 남겨 false를 반환합니다. 셋째 block은 data가 되며 앞 두 block을 metadata에 연결합니다. 서로 다른 order의 block을 크기 확인 없이 섞지 않는 구조입니다.
 * order1의 A→B→C 도착을 표로 적고 처음 두 반환false·셋째true를 확인하세요. allocator에 넘길 block과 metadata로 예약한 block의 소유권을 구별하며 실제 buddy free는 callback 모델입니다.
 */
bool kmsan_memblock_free_pages(struct page *page, unsigned int order)
{
	struct page *shadow, *origin;

	if (!held_back[order].shadow) {
		held_back[order].shadow = page;
		return false;
	}
	if (!held_back[order].origin) {
		held_back[order].origin = page;
		return false;
	}
	shadow = held_back[order].shadow;
	origin = held_back[order].origin;
	kmsan_setup_meta(page, shadow, origin, order);

	held_back[order].shadow = NULL;
	held_back[order].origin = NULL;
	return true;
}

