/* 학습 해설
 * KMSAN no-sanitize memset·직접 helper와 일반 memset
 * 실제 Linux subsystem API의 설정별 가용성·반환 계약·인자 평가·문서와 구현의 차이·오류 시 검사 비활성화를 이해합니다.
 * 활성 memset_no_sanitize_memory는 __memset을, disabled는 일반 memset을 호출합니다. 실제 data를 byte c로 채우지만 활성에서는 KMSAN instrumentation을 우회하는 목적입니다. metadata unpoison을 같이 하는 함수로 설명하지 않으며 tracking 상태 유지가 caller에게 필요한 이유를 확인합니다.
 * 원본 두 inline에서32byte를0xab로 채우고 반환 주소·모든 byte를 확인하세요. 활성 __memset은 호출 recorder와 libc 모델이며 실제 compiler instrumentation 차이는 LLVM kernel build에서 확인해야 합니다.
 */
static inline void *memset_no_sanitize_memory(void *s, int c, size_t n)
{
	return __memset(s, c, n);
}

extern bool kmsan_enabled;
extern int panic_on_kmsan;

/*
 * KMSAN performs a lot of consistency checks that are currently enabled by
 * default. BUG_ON is normally discouraged in the kernel, unless used for
 * debugging, but KMSAN itself is a debugging tool, so it makes little sense to
 * recover if something goes wrong.
 */
#define KMSAN_WARN_ON(cond)                                           \
	({                                                            \
		const bool __cond = WARN_ON(cond);                    \
		if (unlikely(__cond)) {                               \
			WRITE_ONCE(kmsan_enabled, false);             \
			if (panic_on_kmsan) {                         \
				/* Can't call panic() here because */ \
				/* of uaccess checks. */              \
				BUG();                                \
			}                                             \
		}                                                     \
		__cond;                                               \

